    mode: StakeOptionsMode,
    options: { [key: string]: string },
  ): Promise<void> {
    const stakeableBalance = await this.stakeableBalance(assetId, mode, options);

    if (new Decimal(stakeableBalance).lessThan(amount.toString())) {
