   * Returns the bonded stake amount of the StakingBalance.
   *
   * @returns The Balance.
   */
  public bondedStake(): Balance {
    return Balance.fromModel(this.model.bonded_stake);
  }

  /**
   * Returns the unbonded stake amount of the StakingBalance.
   *
